# Generated by subscriber-engine to reopen session {{sessionId}} in this window. It resumes the agent's conversation and
# records nothing: the session's state and exit record stay as they were. Only validated values are substituted into this file;
# the repository is a quoted literal.
$ErrorActionPreference = 'Continue'
$session = '{{sessionFolder}}'
$Host.UI.RawUI.WindowTitle = '{{title}} (reopened)'
Set-Location -LiteralPath '{{repository}}'
& {{command}} --resume {{sessionId}}{{permissionFlags}} --add-dir $session --log-dir (Join-Path $session 'logs-reopened')
exit $LASTEXITCODE
